import pytest
from marshmallow import fields, Schema

def test_datetime_in_list():
    class MySchema(Schema):
        times = fields.List(fields.DateTime())

    s = MySchema()
    assert s is not None

def test_datetime_in_tuple():
    class MySchema(Schema):
        times = fields.Tuple((fields.DateTime(),))

    s = MySchema()
    assert s is not None

def test_date_in_list():
    class MySchema(Schema):
        dates = fields.List(fields.Date())

    s = MySchema()
    assert s is not None

def test_datetime_format_inherits_from_schema_opts():
    class MySchema(Schema):
        class Meta:
            datetimeformat = "%Y-%m-%d"
        times = fields.List(fields.DateTime())

    s = MySchema()
    assert s.fields["times"].inner.format == "%Y-%m-%d"
